const corpo = $('Recebe pedido do app').first().json.body || {};
const acesso = $('Confere acesso').first().json;
const texto = (v) => String(v ?? '').trim();
const id = (v) => (/^rec[A-Za-z0-9]{14}$/.test(texto(v)) ? texto(v) : '');

const ACOES = ['listar', 'iniciar', 'desfazer', 'concluir'];
const acao = ACOES.includes(texto(corpo.acao)) ? texto(corpo.acao) : '';
const chamadoId = id(corpo.chamadoId);
const visitaId = id(corpo.visitaId);
const resumo = texto(corpo.resumo).slice(0, 5000);

let erro = '';
if (!acao) erro = 'Ação inválida.';
else if (acao === 'iniciar' && !chamadoId) erro = 'Chamado inválido.';
else if ((acao === 'desfazer' || acao === 'concluir') && !visitaId) erro = 'Atendimento inválido.';
else if (acao === 'concluir' && !resumo) erro = 'Escreva o que foi feito.';

return [{
  json: {
    acao, chamadoId, visitaId, resumo,
    recebidoPor: texto(corpo.recebidoPor).slice(0, 120),
    confirmarData: texto(corpo.confirmarData) === 'true',
    usuarioId: acesso.usuarioId || '',
    erro,
  },
}];

const itens = $input.all().map((i) => i.json);
// Airtable fora do ar não pode parecer "nenhum atendimento em andamento".
if (itens.some((j) => j && j.error)) {
  return [{ json: { ok: false, mensagem: 'Não foi possível carregar os atendimentos agora.' } }];
}
const visitas = itens
  .filter((j) => j && j.id)
  .map((j) => {
    const f = j.fields || {};
    return {
      id: j.id,
      chamadoId: (f.Chamado || [])[0] || '',
      inicioReal: f.Inicio_Real || '',
      iniciadoPor: f.Iniciado_Por || '',
    };
  })
  .filter((v) => v.chamadoId);
return [{ json: { ok: true, visitas } }];

const usuario = $('Busca usuario').first().json;
const quem = (usuario && usuario.fields && usuario.fields.Nome) || 'senha de acesso';
const agora = new Date().toISOString();
const hora = (iso) => new Date(iso).toLocaleTimeString('pt-BR', { timeZone: 'America/Sao_Paulo', hour: '2-digit', minute: '2-digit' });
const dataHora = (iso) => new Date(iso).toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo', day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' }).replace(',', '');
const comLinha = (historico, linha) => (historico ? historico + '\n' : '') + agora + ' -- ' + linha;
const recusa = (mensagem) => [{ json: { pode: false, resposta: { ok: false, mensagem } } }];
const entrada = $('Le entrada').first().json;
const r = $('Busca chamado').first().json;
if (!r || !r.id) return recusa('Chamado não encontrado.');
const f = r.fields || {};
const status = f.Status || '';

if (status === 'Em andamento') return recusa('Esse chamado já está em andamento.');
if (status === 'Concluído' || status === 'Cancelado') return recusa('Esse chamado já está ' + status.toLowerCase() + '.');
if (!f.Reservado_Inicio) return recusa('Esse chamado ainda não está na agenda.');
// Só começa com data confirmada -- ou confirmando agora, no mesmo toque.
if (status !== 'Agendado' && !(status === 'Aguardando confirmação de data' && entrada.confirmarData)) {
  return recusa('Confirme a data do chamado antes de iniciar.');
}

const orcamento = f.Tipo_Chamado === 'Orçamento';
const rotulo = new Date().toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo', day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit' }).replace(',', '');
const linha = (orcamento ? 'Visita de orçamento iniciada' : 'Atendimento iniciado') + ' por ' + quem
  + (status !== 'Agendado' ? ' (data confirmada na hora)' : '') + '.';

// ---- O bloco da Agenda passa a começar na hora REAL, com a mesma duração ----
// Adiantou: só o próprio chamado anda pra mais cedo; os seguintes ficam onde
// estão (o dono decide se aproveita a folga). Atrasou: o fim também anda, e o
// que passar a invadir o próximo empurra ele em cascata (mesma regra da Agenda).
const MIN = 60000;
const t = (iso) => new Date(iso).getTime();
const iso = (ms) => new Date(ms).toISOString();
const iniAntes = t(f.Reservado_Inicio);
const fimAntes = f.Reservado_Fim ? t(f.Reservado_Fim) : null;
const duracao = fimAntes !== null && fimAntes > iniAntes ? fimAntes - iniAntes : null;
const niCandidato = Math.floor(Date.now() / MIN) * MIN;
// Sem horário de fim (só o dia marcado) ou diferença de menos de 1 min: não mexe.
const mexe = duracao !== null && Math.abs(niCandidato - iniAntes) >= MIN;
const ni = mexe ? niCandidato : iniAntes;
const nf = mexe ? ni + duracao : fimAntes;

const registros = [];
const antes = [];
const movidos = [];
const sobrepostos = [];
const fieldsPrincipal = { Status: 'Em andamento' };
let histPrincipal = linha;

if (mexe) {
  fieldsPrincipal.Reservado_Inicio = iso(ni);
  fieldsPrincipal.Reservado_Fim = iso(nf);
  histPrincipal += ' O bloco da Agenda passou a mostrar o horário real: previsto ' + dataHora(iniAntes) + ' às ' + hora(fimAntes)
    + ', agora ' + dataHora(ni) + ' às ' + hora(nf) + '.';
  antes.push({ id: r.id, ini: iso(iniAntes), fim: iso(fimAntes), depoisIni: iso(ni), depoisFim: iso(nf) });

  if (ni > iniAntes) {
    // Atrasou: cascata. Só considera quem vem depois do início previsto.
    const lista = (($input.first().json || {}).records || [])
      .filter((o) => o.id !== r.id && o.fields && o.fields.Reservado_Inicio && o.fields.Reservado_Fim
        && t(o.fields.Reservado_Inicio) >= iniAntes
        && !['Concluído', 'Cancelado'].includes(o.fields.Status || ''))
      .sort((a, b) => t(a.fields.Reservado_Inicio) - t(b.fields.Reservado_Inicio));
    let corte = nf;
    for (const o of lista) {
      const oi = t(o.fields.Reservado_Inicio);
      const ofim = t(o.fields.Reservado_Fim);
      if (oi >= corte) break;
      if (o.fields.Status === 'Em andamento' || movidos.length >= 9) { sobrepostos.push(o.fields.Numero_Chamado); continue; }
      const desloc = corte - oi;
      const novoIni = corte;
      const novoFim = ofim + desloc;
      // Chegada combinada com o cliente nesse chamado: a cascata continua, mas a tela
      // avisa e sugere a mesma folga na hora combinada (o dono decide se muda).
      const hc = String(o.fields.Horario_Combinado_Cliente || '').trim();
      let sugestao = '';
      const mHc = /^([01]?\d|2[0-3]):([0-5]\d)$/.exec(hc);
      if (mHc) { const tot = Number(mHc[1]) * 60 + Number(mHc[2]) + Math.round(desloc / MIN); if (tot < 24 * 60) sugestao = String(Math.floor(tot / 60)).padStart(2, '0') + ':' + String(tot % 60).padStart(2, '0'); }
      movidos.push({ id: o.id, numero: o.fields.Numero_Chamado, cliente: o.fields.Cliente_Nome || '', reservadoInicio: iso(novoIni), reservadoFim: iso(novoFim),
        horarioCombinado: hc, sugestaoHorarioCombinado: sugestao });
      antes.push({ id: o.id, ini: iso(oi), fim: iso(ofim), depoisIni: iso(novoIni), depoisFim: iso(novoFim) });
      registros.push({ id: o.id, fields: {
        Reservado_Inicio: iso(novoIni), Reservado_Fim: iso(novoFim),
        Historico: comLinha(o.fields.Historico, 'horário empurrado: ' + dataHora(oi) + ' -> ' + dataHora(novoIni)
          + ' [o Chamado #' + (f.Numero_Chamado || '') + ' começou mais tarde que o previsto]'),
      } });
      corte = novoFim;
    }
  }
}
fieldsPrincipal.Historico = comLinha(f.Historico, histPrincipal);
registros.unshift({ id: r.id, fields: fieldsPrincipal });

// Pra voltar atrás se a visita não puder ser criada: devolve tudo como estava.
const originais = new Map((($input.first().json || {}).records || []).map((o) => [o.id, o.fields || {}]));
const desfazRegistros = [{ id: r.id, fields: { Status: status, Historico: f.Historico || '',
  ...(mexe ? { Reservado_Inicio: f.Reservado_Inicio, Reservado_Fim: f.Reservado_Fim } : {}) } }];
for (const m of movidos) {
  const o = originais.get(m.id) || {};
  desfazRegistros.push({ id: m.id, fields: { Reservado_Inicio: o.Reservado_Inicio, Reservado_Fim: o.Reservado_Fim, Historico: o.Historico || '' } });
}

return [{
  json: {
    pode: true,
    chamadoId: r.id,
    desfazChamado: { typecast: true, records: desfazRegistros },
    patchChamado: { typecast: true, records: registros },
    criaVisita: { typecast: true, records: [{ fields: {
      Visita: 'Chamado #' + (f.Numero_Chamado || '') + ' — ' + rotulo,
      Chamado: [r.id], Situacao: 'Em andamento', Inicio_Real: agora, Iniciado_Por: quem,
      ...(antes.length ? { Reservado_Antes: JSON.stringify(antes) } : {}),
    } }] },
    inicioReal: agora,
    iniciadoPor: quem,
    horario: mexe ? { reservadoInicio: iso(ni), reservadoFim: iso(nf), previstoInicio: iso(iniAntes), previstoFim: iso(fimAntes) } : null,
    movidos,
    sobrepostos,
  },
}];

const d = $('Decide inicio').first().json;
const criada = ($input.first().json.records || [])[0] || {};
return [{ json: { ok: true, visita: { id: criada.id, chamadoId: d.chamadoId, inicioReal: d.inicioReal, iniciadoPor: d.iniciadoPor },
  horario: d.horario, movidos: d.movidos, sobrepostos: d.sobrepostos } }];

const usuario = $('Busca usuario').first().json;
const quem = (usuario && usuario.fields && usuario.fields.Nome) || 'senha de acesso';
const agora = new Date().toISOString();
const dataHora = (iso) => new Date(iso).toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo', day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' }).replace(',', '');
const comLinha = (historico, linha) => (historico ? historico + '\n' : '') + agora + ' -- ' + linha;
const recusa = (mensagem) => [{ json: { pode: false, resposta: { ok: false, mensagem } } }];
const visita = $('Busca visita').first().json;
const chamado = $('Busca chamado da visita').first().json;
const v = visita.fields || {};
const f = chamado.fields || {};
if (v.Situacao !== 'Em andamento') return recusa('Esse atendimento já foi encerrado.');
// Desfazer é pra toque errado: vale só logo depois de iniciar.
if (Date.now() - new Date(v.Inicio_Real).getTime() > 15 * 60 * 1000) {
  return recusa('Já passou muito tempo pra desfazer. Encerre o atendimento normalmente.');
}
const patch = { typecast: true, records: [{ id: chamado.id, fields: { Historico: comLinha(f.Historico, 'Início desfeito por ' + quem + '.') } }] };
// Só devolve pra "Agendado" se ainda estiver em andamento (ninguém mudou no meio).
if (f.Status === 'Em andamento') patch.records[0].fields.Status = 'Agendado';

// Devolve os horários de antes de iniciar (o do chamado e os dos empurrados),
// mas só de quem ainda está exatamente onde o início deixou: se o dono já mexeu
// no horário de algum, esse não é tocado.
let antes = [];
try { antes = JSON.parse(v.Reservado_Antes || '[]'); } catch (e) { antes = []; }
const atuais = new Map((($input.first().json || {}).records || []).map((o) => [o.id, o]));
atuais.set(chamado.id, chamado);
const mesmo = (a, b) => a && b && new Date(a).getTime() === new Date(b).getTime();
const restaurados = [];
for (const e of antes) {
  const atual = atuais.get(e.id);
  if (!atual) continue;
  const af = atual.fields || {};
  if (!mesmo(af.Reservado_Inicio, e.depoisIni) || !mesmo(af.Reservado_Fim, e.depoisFim)) continue;
  restaurados.push({ id: e.id, reservadoInicio: e.ini, reservadoFim: e.fim });
  if (e.id === chamado.id) {
    patch.records[0].fields.Reservado_Inicio = e.ini;
    patch.records[0].fields.Reservado_Fim = e.fim;
  } else {
    patch.records.push({ id: e.id, fields: { Reservado_Inicio: e.ini, Reservado_Fim: e.fim,
      Historico: comLinha(af.Historico, 'horário devolvido: ' + dataHora(e.depoisIni) + ' -> ' + dataHora(e.ini) + ' [início do Chamado #' + (f.Numero_Chamado || '') + ' desfeito]') } });
  }
}
return [{ json: { pode: true, visitaId: visita.id, chamadoId: chamado.id, patchChamado: patch, restaurados } }];

const usuario = $('Busca usuario').first().json;
const quem = (usuario && usuario.fields && usuario.fields.Nome) || 'senha de acesso';
const agora = new Date().toISOString();
const hora = (iso) => new Date(iso).toLocaleTimeString('pt-BR', { timeZone: 'America/Sao_Paulo', hour: '2-digit', minute: '2-digit' });
const comLinha = (historico, linha) => (historico ? historico + '\n' : '') + agora + ' -- ' + linha;
const recusa = (mensagem) => [{ json: { pode: false, resposta: { ok: false, mensagem } } }];
const entrada = $('Le entrada').first().json;
const visita = $('Busca visita p/ concluir').first().json;
const chamado = $input.first().json;
const v = visita.fields || {};
const f = chamado.fields || {};
if (v.Situacao !== 'Em andamento') return recusa('Esse atendimento já foi encerrado.');

const orcamento = f.Tipo_Chamado === 'Orçamento';
const periodo = ' (' + hora(v.Inicio_Real) + ' às ' + hora(agora) + ')';
const camposChamado = {};
let novoStatus = f.Status || '';
let horarioReal = null; // só atendimento normal concluído: o que a Agenda passa a mostrar
if (f.Status === 'Cancelado') {
  // Cancelado no meio do caminho: fecha só a visita, não ressuscita o chamado.
  camposChamado.Historico = comLinha(f.Historico, 'Visita encerrada por ' + quem + periodo + '.');
} else if (orcamento) {
  // Visita de orçamento feita: o próximo passo é mandar o preço, e a execução
  // (se aprovada) ganha agendamento novo. Volta pra fila, sem data.
  novoStatus = 'Aguardando confirmação de data';
  Object.assign(camposChamado, {
    Status: novoStatus, Reservado_Inicio: null, Reservado_Fim: null,
    Historico: comLinha(f.Historico, 'Visita de orçamento encerrada por ' + quem + periodo + '. Voltou pra fila até o orçamento ser enviado.'),
  });
} else {
  novoStatus = 'Concluído';
  // Concluído continua na Agenda (cinza, editável). O bloco passa a mostrar o horário
  // REAL da visita; o previsto fica anotado no histórico. Fim nunca antes de 1 min
  // depois do início real (a Agenda exige fim depois do início).
  const fimReal = new Date(Math.max(new Date(agora).getTime(), new Date(v.Inicio_Real).getTime() + 60000)).toISOString();
  horarioReal = { reservadoInicio: v.Inicio_Real, reservadoFim: fimReal };
  const previsto = f.Reservado_Inicio && f.Reservado_Fim
    ? 'previsto ' + hora(f.Reservado_Inicio) + ' às ' + hora(f.Reservado_Fim) : 'sem horário previsto';
  Object.assign(camposChamado, {
    Status: novoStatus,
    Reservado_Inicio: horarioReal.reservadoInicio, Reservado_Fim: horarioReal.reservadoFim,
    Historico: comLinha(f.Historico, 'Atendimento concluído por ' + quem + periodo + '. A Agenda passou a mostrar o horário real (' + previsto + ').'),
  });
}

return [{
  json: {
    pode: true,
    chamadoId: chamado.id,
    novoStatus,
    orcamento,
    horarioReal,
    patchChamado: { typecast: true, records: [{ id: chamado.id, fields: camposChamado }] },
    patchVisita: { typecast: true, records: [{ id: visita.id, fields: {
      Situacao: 'Concluída', Fim_Real: agora, Resumo: entrada.resumo,
      Recebido_Por: entrada.recebidoPor, Concluido_Por: quem,
    } }] },
  },
}];

const d = $('Decide conclusao').first().json;
const json = { ok: true, chamadoId: d.chamadoId, novoStatus: d.novoStatus, orcamento: d.orcamento };
if (d.horarioReal) { json.reservadoInicio = d.horarioReal.reservadoInicio; json.reservadoFim = d.horarioReal.reservadoFim; }
return [{ json }];
